entries[92605] = { ["name"] = "Goldener Kelch", ["text"] = "Wird beim Aufheben gebunden\n\"Aus irgendeinem Grund seid Ihr ziemlich stolz auf Euch, während Ihr ihn haltet.\"\nVerkaufspreis:" }
