entries[92615] = { ["name"] = "Tarics erlesene Juwelen", ["text"] = "Wird beim Aufheben gebunden\n\"Jemand wäre sicherlich erleichtert, die zurückzubekommen... falls sie jemand zurückbringen sollte.\"\nVerkaufspreis:" }
entries[92616] = { ["name"] = "Goldene Fruchtschale", ["text"] = "Wird beim Aufheben gebunden\n\"Ist vermutlich wertvoller, als sie aussieht...\"" }
entries[92617] = { ["name"] = "Goldene Fruchtschale", ["text"] = "Wird beim Aufheben gebunden\n\"Das Obst darin ist schon lange verfault.\"\nVerkaufspreis:" }
entries[92618] = { ["name"] = "Kunstvolles Porträt", ["text"] = "Wird beim Aufheben gebunden\n\"Allein der Rahmen ist aus purem Gold...\"" }
entries[92619] = { ["name"] = "Kunstvolles Porträt", ["text"] = "Wird beim Aufheben gebunden\n\"Die Inschrift verlautet: \"Eine Ergründung von Farbe und Verteufelung\"\"\nVerkaufspreis:" }
entries[92620] = { ["name"] = "Ein ausgefranster Knoten", ["text"] = "Wird beim Aufheben gebunden\n\"Ist der noch zu retten? Ein ausgefranster Knoten...\"" }
entries[92621] = { ["name"] = "Ein ausgefranster Knoten", ["text"] = "Wird beim Aufheben gebunden\n\"Könnte einige Münzen wert sein, wenn Ihr ihn aufgedröselt bekommt...\"\nVerkaufspreis:" }
