entries[92623] = { ["name"] = "Uralter orcischer Schild", ["text"] = "Wird beim Aufheben gebunden\n\"Ein uraltes Relikt der Mag'harklans aus der Zeit vor der Legion.\"\nVerkaufspreis:" }
