entries[92707] = { ["name"] = "Glutkätzchen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euer Glutkätzchen beschwören oder wieder freigeben." }
entries[92708] = { ["name"] = "Geisterfalle", ["text"] = "Questgegenstand\n\"Eine deaktivierte Geisterfalle. Hoffentlich kann die Archäologische Akademie daraus immer noch die benötigten Informationen ableiten.\"" }
entries[92718] = { ["name"] = "Preisgeldbeutel", ["text"] = "Wird beim Aufheben gebunden\n\"Euer Anteil am \"Preisgeld\" und was sonst noch auf dem Boden der Arena herumlag.\"\n<Zum Öffnen rechtsklicken>" }
