entries[92724] = { ["name"] = "Schnelles Windross", ["text"] = "Wird beim Aufheben gebunden\nReittier\nBenötigt Stufe 20\nBenötigt Unerfahrener Reiter\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört ein schnelles Windross oder gibt es wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an." }
entries[92726] = { ["name"] = "Bipsis Handschuhe", ["text"] = "Wird beim Anlegen gebunden\nHände Stoff\n869 Rüstung\n+454 Ausdauer\n+301 Intelligenz\nErhöht Eure Tempowertung um + 202.\nErhöht Eure Meisterschaftswertung um + 202.\nHaltbarkeit 50 / 50\nBenötigt Stufe 85\nVerkaufspreis:" }
entries[92727] = { ["name"] = "Glyphe 'Diskrete Magie'", ["text"] = "Geringe Glyphe\nKlassen: Magier\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Zauber 'Netherorkan', 'Lebende Bombe', 'Frostbombe', 'Arkanbeschuss' und 'Infernoschlag' wirken sich nun nicht mehr auf Ziele aus, die weiter als 5 Meter vom Primärziel entfernt sind.\nVerkaufspreis:" }
entries[92735] = { ["name"] = "Meng-dos Essenz", ["text"] = "Questgegenstand\n\"Fühlt sich unglaublich schwer und heiß an.\"" }
entries[92736] = { ["name"] = "Gen-lis Essenz", ["text"] = "Questgegenstand\n\"Die Bewegungen dieser Staubpartikel sind unberechenbar. Wenn Ihr die Hände bewegt, schweben sie um sie herum.\"" }
entries[92738] = { ["name"] = "Safarihelm", ["text"] = "Accountgebunden\nSpielzeug\nBenötigt Kampfhaustiertraining\nBenutzen: Erhaltene Haustierkampferfahrung um 10% erhöht. (3 Sek. Abklingzeit)\n\"Weidmannsheil!\"\nVerkaufspreis:" }
entries[92739] = { ["name"] = "Deplatziertes Fass", ["text"] = "Ein wenig Geduld\nEinzigartig (5)\nBenutzen: Ein bisschen \"Schmiermittel\" sorgt für klare Köpfe unter den Pandarenarbeitern und erhöht ihre Arbeitsgeschwindigkeit permanent um 60% des Grundwerts. Bis zu 3-mal stapelbar. 1 Sek. Abklingzeit." }
entries[92740] = { ["name"] = "Perfekter Kampfstein", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wertet ein Kampfhaustier jeglicher Art sofort zu epischer Qualität auf. Haustiere der Stufe 15 und höher verlieren dadurch bis zu zwei Stufen." }
entries[92741] = { ["name"] = "Makelloser Kampfstein", ["text"] = "Benutzen: Wertet alle Typen von Kampfhaustieren sofort zu seltener Qualität auf. Haustiere der Stufe 15 und höher verlieren dadurch bis zu zwei Stufen." }
entries[92742] = { ["name"] = "Polierter Kampfstein", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wertet alle Typen von Kampfhaustieren sofort zu ungewöhnlicher Qualität auf. Haustiere der Stufe 15 und höher verlieren dadurch bis zu zwei Stufen.\nVerkaufspreis:" }
entries[92743] = { ["name"] = "Krasarieisen", ["text"] = "Ein wenig Geduld\nEinzigartig (5)\nBenutzen: Kleine Leute arbeiten am besten, wenn ihnen viel Eisen zur Verfügung steht. Erhöht 1 Min. lang die Arbeitsgeschwindigkeit von Gnomen- und Zwergenarbeitern um 30% des Grundwerts. Bis zu 3-mal stapelbar." }
entries[92744] = { ["name"] = "Schwerer Goldbeutel", ["text"] = "Wird beim Aufheben gebunden\n\"Das ist eine Menge Gold.\"\n<Zum Öffnen rechtsklicken>" }
entries[92745] = { ["name"] = "Flüssiges Feuer", ["text"] = "Ein wenig Geduld\nEinzigartig (5)\nBenutzen: Hilft beim Brauen von pandarischem Sprengbräu. 1 Sek. Abklingzeit." }
entries[92746] = { ["name"] = "Tragbarer Kühlschrank", ["text"] = "Wird beim Anlegen gebunden\n28 Platz Kochbeutel" }
entries[92747] = { ["name"] = "Fortschrittliche Kühleinheit", ["text"] = "Wird beim Anlegen gebunden\n36 Platz Kochbeutel" }
entries[92748] = { ["name"] = "Tragbarer Kühlschrank", ["text"] = "Wird beim Aufheben gebunden\n32 Platz Kochbeutel" }
entries[92750] = { ["name"] = "Dschungelhopfen", ["text"] = "Ein wenig Geduld\nEinzigartig (5)\nBenutzen: Hilft beim Brauen von pandarischem Sprengbräu. 1 Sek. Abklingzeit." }
entries[92751] = { ["name"] = "Geistgeküsstes Wasser", ["text"] = "Ein wenig Geduld\nEinzigartig\nBenutzen: Erweckt Meister Braunstein oder kann auf einer pandarischen oder nachtelfischen Baustelle verwendet werden. 1 Sek. Abklingzeit." }
entries[92752] = { ["name"] = "Braunkappenpilz", ["text"] = "Questgegenstand\n\"Ein unangenehmer, feuchter Mief geht von diesen kleinen, runden Pilzen aus.\"" }
entries[92753] = { ["name"] = "Spektrale Rückstände", ["text"] = "Questgegenstand\n\"Ein feines, ascheartiges, phosphoreszierendes Pulver.\"" }
entries[92754] = { ["name"] = "Feuerwein von Ruqin", ["text"] = "Questgegenstand\n\"Die weiße Flüssigkeit verströmt einen strengen, beißenden Geruch. Ein kleiner Schluck breitet sich wie Feuer in Eurem Inneren aus, gefolgt von einem warmen, lebendigen Gefühl im Kopf.\"" }
entries[92755] = { ["name"] = "Frische Yakmilch", ["text"] = "Questgegenstand\n\"Diese frische, leicht gelbliche Milch riecht nach... Yak.\"" }
entries[92756] = { ["name"] = "Wein der Erinnerungen", ["text"] = "Questgegenstand\nBenutzen: Werdet Zeuge einer Vision aus Shan Kiens Vergangenheit. (3 Sek. Abklingzeit)\n\"Der Wein riecht nach einem Dutzend Aromen und Gewürzen, die gleichermaßen widerlich und verführerisch sind...\"" }
entries[92763] = { ["name"] = "Helm der Kor'kron", ["text"] = "Questgegenstand\nBenutzen: Fügt den Helm der Kor'kron, die Rüstung der Kor'kron und die Stiefel der Kor'kron zu einer Kor'kron-Verkleidung zusammen. (3 Sek. Abklingzeit)\n\"Der polierte Helm ist verbeult.\"" }
entries[92764] = { ["name"] = "Rüstung der Kor'kron", ["text"] = "Questgegenstand\nBenutzen: Fügt den Helm der Kor'kron, die Rüstung der Kor'kron und die Stiefel der Kor'kron zu einer Kor'kron-Verkleidung zusammen.\n\"Ziemlich schwer.\"" }
entries[92765] = { ["name"] = "Stiefel der Kor'kron", ["text"] = "Questgegenstand\nBenutzen: Fügt den Helm der Kor'kron, die Rüstung der Kor'kron und die Stiefel der Kor'kron zu einer Kor'kron-Verkleidung zusammen.\n\"Da hat wohl jemand seine Füße nicht gewaschen...\"" }
entries[92766] = { ["name"] = "Kor'kron-Verkleidung", ["text"] = "Questgegenstand\nBenutzen: Verkleidet Euch als ein Mitglied der Kor'kron. (3 Sek. Abklingzeit)" }
