entries[92918] = { ["name"] = "Imitation des Blicks des Sargeras", ["text"] = "Wird beim Aufheben gebunden\n\"Bei genauerem Hinsehen stellt es sich als weggeworfenes Defiaskopftuch heraus, das jemand zusammengerollt hat.\"\nVerkaufspreis:" }
