entries[92923] = { ["name"] = "Haufen Stacheleberhauer", ["text"] = "Wird beim Aufheben gebunden\n\"Ihr wisst nicht, wie Mankrik jemanden davon überzeugen konnte, das hier als Pfand zu akzeptieren.\"\nVerkaufspreis:" }
