entries[93158] = { ["name"] = "Abgelaufenes Filmrissbräu", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 90\nBenutzen: Wirft die Flasche. (30 Sek. Abklingzeit)\n\"Zum Trinken taugt es nicht mehr, aber zum Werfen schon.\"\nVerkaufspreis:" }
entries[93159] = { ["name"] = "Verzauberter Schlafsand", ["text"] = "Questgegenstand\nBenutzen: Legt den Drachenfalken der Sonnenhäscher schlafen. Der Drachenfalke der Sonnenhäscher muss über weniger als 35% Gesundheit verfügen." }
entries[93168] = { ["name"] = "Großer gepanzerter Greif", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt eine Allianz-Rasse\nBenötigt Stufe 80\nBenötigt Gekonntes Reiten\nBenötigt Operation Schildwall\n- Ehrfürchtig\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört einen reitbaren großen gepanzerten Greif oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nVerkaufspreis:" }
entries[93169] = { ["name"] = "Großer gepanzerter Wyvern", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt eine Horde-Rasse\nBenötigt Stufe 80\nBenötigt Gekonntes Reiten\nBenötigt Herrschaftsoffensive\n- Ehrfürchtig\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört einen reitbaren großen gepanzerten Wyvern oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nVerkaufspreis:" }
entries[93179] = { ["name"] = "Altmetall", ["text"] = "Questgegenstand\n\"Ein bisschen verbeult und angesengt, aber noch brauchbar.\"" }
entries[93180] = { ["name"] = "Rekonfigurierte Fernsteuerung", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Einfach zielen und drücken! (5 Sek. Abklingzeit)\n\"Überreste eines Warnaufklebers sind erkennbar: Toxisch – Gefährlich!\"" }
entries[93182] = { ["name"] = "Der Straßenfeger des Obersten Kriegsfürsten", ["text"] = "Wird beim Aufheben gebunden\nWaffenhand Streitkolben\n1 - 3 Naturschaden Tempo 2.00\n(1.00 Schaden pro Sekunde)\n+9 Ausdauer\n+ 48 Distanzangriffskraft\nHaltbarkeit 20 / 20\nVerkaufspreis:" }
entries[93187] = { ["name"] = "Instabiler Sprengstoff", ["text"] = "Questgegenstand\nBenutzen: Werft den Sprengstoff auf die Kisten voll Goblinsprengstoff und LAUFT WEG!\n\"Ruckartige Bewegungen und offene Flammen unbedingt vermeiden!\"" }
entries[93189] = { ["name"] = "Artefakt der Korun", ["text"] = "Questgegenstand\n\"Diese Artefakte beschreiben, wie die Korun die Macht des Sha für sich nutzen konnten.\"" }
entries[93190] = { ["name"] = "Sha-berührte Klaue", ["text"] = "Questgegenstand\n\"Die Hand des Spruchwirkers der Korun ist zu einer monströsen Klaue mutiert. Dunkle Energie geht von ihr aus. Hilda und Brann könnten sich dafür interessieren.\"" }
entries[93191] = { ["name"] = "Rostiges Ventil", ["text"] = "Questgegenstand\n\"Dieses verrostete Ventil hat bessere Zeiten erlebt.\"" }
entries[93194] = { ["name"] = "Blutverschmierte Einladung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Stufe 90\nBenutzen: Verschafft allen Charakteren Eures Accounts Zugang zur Kampfgilde.\nVerkaufspreis:" }
entries[93195] = { ["name"] = "Mitgliedspass der Kampfgilde", ["text"] = "Benötigt eine Allianz-Rasse\nBenötigt Stufe 90\nBenutzen: Verschafft allen Charakteren Eures Accounts Zugang zur Kampfgilde." }
entries[93197] = { ["name"] = "Glyphe 'Supernova'", ["text"] = "Erhebliche Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Ihr sterbt, erleiden alle Gegner innerhalb von 8 Metern pro verfügbarem instabilem Funken Schaden in Höhe von 10% Eurer Maximalgesundheit.\nVerkaufspreis:" }
entries[93198] = { ["name"] = "Foliant des Tigers", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 85\n\"Enthält 10 Rollen der Weisheit.\"\n<Zum Öffnen rechtsklicken>" }
