entries[93202] = { ["name"] = "Glyphe 'Spontanteleportation'", ["text"] = "Geringe Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure dämonischen Tore werden automatisch aktiviert, wenn Ihr Euch ihnen nähert.\nVerkaufspreis:" }
entries[93203] = { ["name"] = "Glyphe 'Fokus'", ["text"] = "Geringe Glyphe\nKlassen: Druide\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert den Radius von 'Sternenregen' um 50%.\nVerkaufspreis:" }
entries[93204] = { ["name"] = "Delaris' Prisma", ["text"] = "Questgegenstand\nBenutzen: Beschwört ein Abbild dessen, was Wichtel am meisten fürchten. (3 Sek. Abklingzeit)\n\"So wunderschön bunt!\"" }
entries[93205] = { ["name"] = "Pierre", ["text"] = "Benutzen: Platziert einen thermischen Amboss zu Euren Füßen, der allen in der Nähe befindlichen Charakteren erlaubt, sowohl einen Amboss als auch eine Schmiede zu benutzen. Hält 5 Min. lang an. (5 Min Abklingzeit)\n20 Aufladungen\n\"Ein raffinierter Herd. Für einen raffinierten Koch.\"" }
entries[93208] = { ["name"] = "Dunkelmond-G.R.O.G.", ["text"] = "Benutzen: Ein starkes alkoholisches Getränk.\n\"Das Grob-Rauschbewirkende-Ohnmächtigskeits-Getränk kann bei Einnahme groben Rausch und Ohnmächtigkeit verursachen. Wer hätte das gedacht!\"\nVerkaufspreis:" }
