entries[93662] = { ["name"] = "Zügel des gepanzerten Himmelskreischers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 80\nBenötigt Gekonntes Reiten\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört einen reitbaren gepanzerten Himmelskreischer oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an." }
entries[93663] = { ["name"] = "Schriftrolle der Verwandlung: Ziege", ["text"] = "Questgegenstand\nBenutzen: Verwandelt den Gegner bis zu 10 Sek. lang in eine hilflose Ziege, die weder Zauber wirken noch angreifen kann und sich 60% langsamer bewegt." }
