entries[93668] = { ["name"] = "Saurierfetisch", ["text"] = "Questgegenstand\nBenutzen: Benutzt diesen Fetisch mit einem Raptor, Compy, Himmelskreischer oder Terrorhorn in den Bestienpferchen, um zu versuchen, die Kontrolle über sie zu erlangen. Die Ergebnisse sind möglicherweise unvorhersehbar. (10 Sek. Abklingzeit)" }
