entries[93671] = { ["name"] = "Schädel des geisterhaften Streitrosses", ["text"] = "Einzigartig\nReittier\nBenötigt Stufe 20\nBenötigt Unerfahrener Reiter\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört ein geisterhaftes Streitross oder gibt es wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an." }
